from itertools import permutations
k = 0
for t in permutations('01234567', 6):
    if t[0] == '0':
        continue
    if any(int(t[i]) % 2 == int(t[i + 1]) % 2 for i in range(5)):
        continue
    if int(''.join(t), 8) % 5 == 0:
        k += 1
print(k)

from itertools import product
k = 0
for t in product('ВОЗДУХ', repeat=5):
    w = ''.join(t)
    if w.count('О') + w.count('У') != 1:
        continue
    if any(x in w for x in ('ХО', 'ОХ', 'ХУ', 'УХ', 'ВО', 'ОВ', 'ВУ', 'УВ')):
        continue
    k += 1
print(k)

