from itertools import product
k = 0
for t in product('0abc', repeat=6):
    s = ''.join(t)
    if s[0] == '0' or s.count('0') < 2:
        continue
    ok = sum(1 for ch in 'abc' if s.count(ch) == 2 and ch * 2 in s)
    if ok == 1:
        k += 1
print(k)
